import {test,expect} from '@playwright/test';
import {start,settled,seed,checkpoint,enterBoss,winBoss,solveDiscovery,fight} from './helpers.js';
import {SAVE_KEY} from '../src/progress.js';
const saved=page=>page.evaluate(key=>localStorage.getItem(key),SAVE_KEY);
test('trial, reward, collected diamond, restoration and restart survive reload correctly',async({page})=>{
 await start(page);await enterBoss(page,'form');await page.getByRole('button',{name:'Begin the encounter',exact:true}).click();await solveDiscovery(page,'form');
 await page.reload();await page.getByRole('button',{name:'Continue Journey',exact:true}).click();await page.getByRole('button',{name:'Begin the encounter',exact:true}).click();await expect(page.locator('.attack-telegraph')).toBeVisible();expect(await page.evaluate(()=>window.__game.state().bosses.form.discovered)).toBe(true);await fight(page);
 await page.reload();await page.getByRole('button',{name:'Continue Journey',exact:true}).click();await page.getByRole('button',{name:'Recover Diamond of Form',exact:true}).click();await page.reload();await page.getByRole('button',{name:'Continue Journey',exact:true}).click();await expect(page.locator('#panel-kicker')).toHaveText('A GUARDIAN AT REST');await page.getByRole('button',{name:'Return to the shrine',exact:true}).click();await settled(page);await page.getByRole('button',{name:'Pedestal of Form',exact:true}).click();await page.getByRole('button',{name:'Restore Diamond of Form',exact:true}).click();expect(JSON.parse(await saved(page)).bosses.form.placed).toBe(true);
 const before=await saved(page);await page.locator('#journey-button').click();await page.getByRole('button',{name:'Restart journey',exact:true}).click();await page.locator('#cancel-restart').click();expect(await saved(page)).toBe(before);await page.locator('#journey-button').click();await page.getByRole('button',{name:'Restart journey',exact:true}).click();await page.locator('#confirm-restart').click();expect(JSON.parse(await saved(page)).bosses.form.placed).toBe(false);expect(await page.evaluate(()=>window.__game.scene())).toBe('shrine');
});
test('Presenter has every encounter and research chapter while preserving the exact story save',async({page})=>{
 await seed(page,checkpoint());await start(page,true);const before=await saved(page);await page.locator('#journey-button').click();await page.getByRole('button',{name:'Presenter Mode',exact:true}).click();
 for(const name of ['The Hollow Scale','The Twin Warden','The Veiled Mirror','The Nameless Exile']){
  await page.getByRole('button',{name:`Face ${name}`,exact:true}).click();await page.getByRole('button',{name:'Presenter · resolve encounter',exact:true}).click();await expect(page.locator('#panel-kicker')).toHaveText('THE OATH IS QUIET');expect(await saved(page)).toBe(before);await page.locator('#presenter-controls').click();
 }
 await page.getByRole('button',{name:'Research · Memory',exact:true}).click();await expect(page.locator('.research-chart .main-svg').first()).toBeVisible();await page.keyboard.press('Escape');await page.locator('#presenter-controls').click();await page.getByRole('button',{name:'Replay the final revelation',exact:true}).click();await page.getByRole('button',{name:'Continue the revelation'}).click();await page.getByRole('button',{name:'Continue the revelation'}).click();await page.getByRole('button',{name:'Unite the evidence'}).click();await page.getByRole('button',{name:'Explore the research',exact:true}).click();await expect(page.locator('#codex-body')).toContainText('88.12%');await page.getByRole('button',{name:'Close Research Codex'}).click();await page.locator('#return-story').click();await settled(page);expect(await saved(page)).toBe(before);expect(await page.evaluate(()=>window.__game.mode())).toBe('story');
});
test('Presenter launched without a save returns to the title without creating progress',async({page})=>{
 await page.goto('http://127.0.0.1:5173/?profile=1');await page.getByRole('button',{name:'Presenter Mode',exact:true}).click();await page.getByRole('button',{name:'Return to Story',exact:true}).last().click();await expect(page.locator('#intro')).toBeVisible();expect(await saved(page)).toBeNull();await page.getByRole('button',{name:'New Journey',exact:true}).click();expect(JSON.parse(await saved(page)).started).toBe(true);
});
test('corrupt and unavailable storage do not stop a complete encounter',async({page})=>{
 await page.addInitScript(key=>localStorage.setItem(key,'{broken'),SAVE_KEY);await start(page);expect(await page.evaluate(()=>window.__game.state().started)).toBe(true);await page.context().clearCookies();
 await page.addInitScript(()=>{Storage.prototype.getItem=()=>{throw new Error('blocked');};Storage.prototype.setItem=()=>{throw new Error('blocked');};});await page.reload();await page.getByRole('button',{name:'New Journey',exact:true}).click();await settled(page);await enterBoss(page,'division');await winBoss(page,'division');expect(await page.evaluate(()=>window.__game.state().bosses.division.collected)).toBe(true);
});
